const GOSPELS = new Set(["MAT", "MRK", "LUK", "JHN"]);
const CATHOLIC = new Set(["JAS", "1PE", "2PE", "1JN", "2JN", "3JN", "JUD"]);

/** The reading's place in the service: [Amharic, English]. */
function kind(book) {
  if (book === "PSA" || book === "REF") return ["ምስባክ", "Psalm"];
  if (GOSPELS.has(book)) return ["ወንጌል", "Gospel"];
  if (book === "ACT") return ["ግብረ ሐዋርያት", "Acts"];
  if (CATHOLIC.has(book)) return ["ሐዋርያ", "Catholic epistle"];
  if (book === "REV") return ["ራእይ", "Revelation"];
  return ["ጳውሎስ", "Pauline epistle"];
}

// Consonants only, with sound-alike letters folded, so ወይርእዩ and ወይርአዩ match.
const FOLD = { "ሐ": "ሀ", "ኀ": "ሀ", "ሠ": "ሰ", "ዐ": "አ", "ፀ": "ጸ" };
function skeleton(word) {
  return [...word].map((c) => {
    const n = c.codePointAt(0);
    if (n < 0x1200 || n > 0x137f) return "";
    const base = String.fromCodePoint(n - ((n - 0x1200) % 8));
    return FOLD[base] || base;
  }).join("");
}
const firstWord = (s) => s.split(/[\s(]/)[0];

function dayOf(month, day) {
  const days = DATA[month];
  return days && days[day - 1] ? days[day - 1] : null;
}

/** A ምስባክ printed only as "say the one of day N": the psalm row it points to. */
function resolve(row, month, depth = 0) {
  const [, , , , , , refDay, refMonth, incipit] = row;
  const m = refMonth || month;
  const target = refDay && depth < 4 ? dayOf(m, refDay) : null;
  if (!target) return null;
  // the named day's ምስባክ may itself be a cross-reference ("say the one of day 4"): follow it
  const psalms = target.r.filter((x) => x[1] === "PSA" || x[1] === "REF");
  const key = skeleton(firstWord(incipit));
  const hit = psalms.find((x) => skeleton(firstWord(x[8])) === key) || psalms.find((x) => x[1] === "PSA") || null;
  return hit && hit[1] === "REF" ? resolve(hit, m, depth + 1) : hit;
}

function reading(row, month) {
  let [service, book, chapter, verse, end, check] = row;
  const incipit = row[8].replace(/\s*\(.*\)\s*$/, "");
  let crossRef = false;
  if (book === "REF") {
    const target = resolve(row, month);
    crossRef = true;
    if (!target) return { service, kind: kind("REF"), book: null, chapter: null, verse: null, end: null, check: true, crossRef, incipit };
    [, book, chapter, verse, end, check] = target;
  }
  return {
    service,                       // "ነግህ" (morning) or "ቅዳሴ" (Kidase)
    kind: kind(book),              // [am, en]
    book: book ? { key: book, am: BOOKS[book][0], en: BOOKS[book][1] } : null,
    chapter, verse,
    end,                           // last verse as printed; "EOC" = to the end of the chapter; null = not given
    check: !!check || chapter == null || verse == null,   // not yet confirmed against the book
    crossRef,                      // printed as "say the ምስባክ of day N" and resolved here
    incipit,                       // opening words (Ge'ez), chant marks removed
  };
}

/** Readings for an Ethiopian date ({month, day}), or null when that day is not transcribed. */
export function readingsFor(date) {
  const d = dayOf(date.month, date.day);
  if (!d) return null;
  const all = d.r.map((row) => reading(row, date.month));
  return {
    commemoration: d.c,
    anaphora: d.a,
    morning: all.filter((x) => x.service === "ነግህ"),
    kidase: all.filter((x) => x.service === "ቅዳሴ"),
  };
}

/** "Matthew 12:1–9", "Romans 8:35 – end of chapter"; lang "am" or "en". */
export function formatReference(x, lang) {
  if (!x.book) return lang === "am" ? "ምስባክ (ማጣቀሻ)" : "Psalm (cross-reference)";
  const name = lang === "am" ? x.book.am : x.book.en;
  if (x.chapter == null) return name;
  let s = `${name} ${x.chapter}:${x.verse ?? "?"}`;
  if (x.end === "EOC") s += lang === "am" ? " – ፍጻሜ ምዕራፍ" : " – end of chapter";
  else if (x.end != null) s += x.end < x.verse ? `–${x.chapter + 1}:${x.end}` : `–${x.end}`;
  return s;
}

/** The key of a reading's verse text in passages/NN.json (null for an unresolved reading). */
export function passageKey(x) {
  if (!x.book || x.chapter == null || x.verse == null) return null;
  return `${x.book.key} ${x.chapter}:${x.verse}-${x.end ?? "m"}`;
}

/** Month numbers (1–13) that have readings. */
export const READINGS_MONTHS = Object.keys(DATA).map(Number);
